function h({registerIndicator:u,sourceValues:m,nulls:p}){u({id:"oa-rgma",name:"Recursive Gaussian Moving Average (RGMA)",category:"Trends IIR",placement:"onchart",inputs:[{key:"period",type:"number",label:"Period",default:10,min:1,max:5e3,step:1},{key:"passes",type:"number",label:"Passes",default:3,min:1,max:10,step:1,tooltip:"More passes create more Gaussian-like smoothing"},{key:"source",type:"source",label:"Source",default:"close"}],plots:[{key:"rgma",type:"line",title:"RGMA",style:{color:"#ffeb3b",lineWidth:2}}],calc(l,r){const f=Math.max(1,Math.floor(Number(r.period)||10)),o=Math.min(10,Math.max(1,Math.floor(Number(r.passes)||3))),d=m(l,r.source??"close"),i=2/(f/Math.sqrt(o)+1),e=new Array(o).fill(NaN);let c=!1;const n=new Array(l.length).fill(NaN);for(let a=0;a<l.length;a++){const s=d[a];if(Number.isFinite(s)){if(!c){e.fill(s),c=!0,n[a]=s;continue}e[0]=i*(s-e[0])+e[0];for(let t=1;t<o;t++)e[t]=i*(e[t-1]-e[t])+e[t];n[a]=e[o-1]}}return{rgma:p(n)}}})}export{h as default};
